head.script:
scwin.userExp = function(col1, col2, targetColValue) { //debugger;
    var value = "";
    if (targetColValue == "A") {
        value = col1 - col2;
    } else if (targetColValue == "B") {
        value = col2 - col1;
    }
    return value;
};
scwin.__checkErrlog = function() {
    return WebSquare.logger.getErrorLog();
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플실행 후 gridView의 (3,4)필드의 값을 확인한다.
    //1. After executing the sample, check the value of (3, 4) field of gridView.
    //Verify 1. -33 값이 보여짐(이전에는 값이 보이지 않음)
    //1. -33 value is displayed (previously no value is shown)
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_body_tbody tr')[6].childNodes[3].innerText == '-33'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. ctrl+마우스 우클릭 > 로그보기를 확인한다.
    //2. Check ctrl + right-click> View log.
    WebSquare.wUnit.addCommand("assert", "scwin.__checkErrlog() == ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    grid1.setData([
        '11', '22', 'A', '',
        '11', '22', 'A', '',
        '11', '22', 'A', '',
        '11', '22', 'B', '',
        '11', '22', 'B', ''
    ]);
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 22-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
